// StartMigrationRequest defines model for StartMigrationRequest.
type StartMigrationRequest struct {
	// AutoSwitch Cut over as soon as data is in sync, without waiting for /switch.
	AutoSwitch *bool `json:"autoSwitch,omitempty"`

	// Canary Before cutover, send this share of read requests (GET, HEAD, OPTIONS) to
	// the target while writes keep going to the source. After each step the
	// gate checks the target's requests over the step. A failed gate puts all
	// reads back on the source and ends the run as `rolled_back`. A step with
	// fewer than `gate.minRequests` requests and no other breach is
	// `inconclusive` and the canary moves on, except at the last step, which
	// must pass with enough requests. When the platform sends synthetic
	// probe reads, a step whose target got fewer than `gate.minRequests` is
	// extended once by another `stepDuration` with more probe reads and then
	// judged over the whole step (at most the last 300s). It is not extended
	// when the errors are already over the limit or when one more batch could
	// not bring enough requests (as at 1%). Gradual steps such as
	// 1, 10, 25, 50, 75, 90, 100 are recommended. Needs gateway mode http.
	Canary *CanaryOptions `json:"canary,omitempty"`

	// Observe After a successful cutover, keep watching the target at the gateway
	// before the run ends. Each step evaluates the gate over that step's
	// requests to the target. A step with fewer than `gate.minRequests`
	// requests, or without gateway data, is inconclusive: it is recorded but
	// is not a violation, because a rollback is a full migration back and is
	// started only on a measured breach. The first violated step ends the
	// observation. The run still ends `succeeded` (the data moved) with the
	// violation in `observe` and `statusReason`. With `autoRollback` the
	// server then starts this run's rollback (as POST
	// /v1/migrations/{runId}/rollback does) as actor `slo-guard`; without it
	// an operator decides. Needs gateway mode http.
	Observe *ObserveOptions `json:"observe,omitempty"`
	PlanRef string          `json:"planRef"`
}

